// 由 tc-console 的 tools/globe/export-hub.mjs 生成，不要手改。地图素材：*.bin 是 gzip 后的 base64，云图、地表（导出那个月的一张）、天空图（webp）是 data URL
// 来源（除云图外都是公有领域）：陆地 Natural Earth 50m/10m；地表 NASA Blue Marble Next Generation；夜光 NASA Black Marble 2016；
// 云 Solar System Scope 8k_earth_clouds（CC BY 4.0，底子是 NASA Blue Marble 云图）；海拔 NOAA ETOPO1；星 Yale Bright Star Catalog 第 5 版；银河 NASA SVS Deep Star Maps 2020
(() => {
  const BIN = {"land-points.bin":"","land-attr.bin":"","land-tone.bin":"","lights.bin":"","stars.bin":"","elev-d.bin":""};
  const CLOUDS = 'data:image/webp;base64,';
  const EARTH = 'data:image/webp;base64,';
  const MW = 'data:image/webp;base64,';
  const SF = 'data:image/webp;base64,';
  const raw = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
  globalThis.TC_EMBED = {
    asset: f => BIN[f] ? new Response(new Blob([raw(BIN[f])]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer() : null,
    url: f => /^earth-\d\d\.webp$/.test(f) ? EARTH : ({ 'clouds-4k.webp': CLOUDS, 'starfield.webp': SF, 'starfield-s.webp': null, 'milkyway.webp': MW })[f] ?? null,
  };
})();
